// spec: .qa/e2e/specs/zmanim.md
// seed: tests/seed.user1.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { setFixedTimeKeepingSession } from '../_helpers/clock';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('זמני היום', () => {
  test('ZM-02 Даты, навигация по дням и годам, место расчёта, ежедневное изучение #6a86f7df @prod-safe', async ({ page }) => {
    const hebrewDate = page.locator('#zmanim-hebrew-date');
    const day = page.locator('#zmanim-day');
    const year = page.locator('#zmanim-year');

    // 1. Зафиксировать часы браузера на 3.10.2026, открыть `/zmanim`, проверить верх экрана.
    // Дата 3.10.2026 нужна по смыслу кейса (3 нажатия «היום הקודם» = переход через границу месяца, ожидаемые
    // еврейские даты из кейса). Часы сдвигаются без потери сессии: сначала свежий токен на реальном времени,
    // затем setFixedTime + expires_at = fake + 1 ч (иначе сервер отвечает 401 — см. .qa/context.md).
    await setFixedTimeKeepingSession(page, new Date('2026-10-03T12:00:00+03:00'));
    await page.goto('/zmanim');
    await expect(hebrewDate).toHaveText('כ״ב תשרי תשפ״ז');
    await expect(day).toHaveText('3 באוקטובר');
    await expect(year).toHaveText('2026');

    // 2. Нажать «היום הקודם» 3 раза — переход через границу месяца на 30.9.2026.
    const prevDay = page.getByLabel('היום הקודם', { exact: true });
    for (let i = 0; i < 3; i++) {
      await prevDay.click();
    }
    await expect(day).toHaveText('30 בספטמבר');
    await expect(year).toHaveText('2026');
    await expect(hebrewDate).toHaveText('י״ט תשרי תשפ״ז');

    // 3. Нажать «השנה הבאה» → 30.9.2027.
    await page.getByLabel('השנה הבאה', { exact: true }).click();
    await expect(day).toHaveText('30 בספטמבר');
    await expect(year).toHaveText('2027');
    await expect(hebrewDate).toHaveText('כ״ח אלול תשפ״ז');

    // 4. Нажать «השנה הקודמת» → снова 30.9.2026.
    await page.getByLabel('השנה הקודמת', { exact: true }).click();
    await expect(day).toHaveText('30 בספטמבר');
    await expect(year).toHaveText('2026');

    // Строка места расчёта
    await expect(page.getByText('הזמנים חושבו עבור פתח תקווה, לפי השעון המקומי שם.')).toBeVisible();

    // 5. Прокрутить к блоку «לימוד יומי».
    const learning = page.locator('#zmanim-learning');
    await learning.scrollIntoViewIfNeeded();
    await expect(learning).toBeVisible();
    const rows = [
      { id: 'learning-dafYomi', label: 'דף יומי בבלי' },
      { id: 'learning-yerushalmiYomi', label: 'דף יומי ירושלמי' },
      { id: 'learning-mishnaBeruraYomi', label: 'עמוד יומי במשנה ברורה' },
    ];
    for (const r of rows) {
      const row = page.locator(`#${r.id}`);
      await expect(row).toContainText(r.label);
      const full = (await row.textContent()) ?? '';
      const value = full.replace(r.label, '').trim();
      // значение не пустое: данные либо «אין נתון כעת»
      expect(value.length).toBeGreaterThan(0);
    }

    // Источник и примечание
    await expect(page.locator('#zmanim-source')).toContainText('Hebcal.com');
    await expect(page.locator('#zmanim-methods-unapproved')).toContainText('טרם אושרו על ידי גורם הלכתי מוסמך');
  });
});
